const putBoxSecret = `-- name: PutBoxSecret :exec

INSERT INTO box_secrets (box_id, app, name, value_enc, size, secret, updated_at)
VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)
ON CONFLICT (box_id, app, name) DO UPDATE SET value_enc = excluded.value_enc, size = excluded.size,
    secret = excluded.secret, updated_at = excluded.updated_at
`

type PutBoxSecretParams struct {
	BoxID     string `json:"boxId"`
	App       string `json:"app"`
	Name      string `json:"name"`
	ValueEnc  []byte `json:"valueEnc"`
	Size      int64  `json:"size"`
	Secret    bool   `json:"secret"`
	UpdatedAt int64  `json:"updatedAt"`
}

// ---------- secrets ----------
func (q *Queries) PutBoxSecret(ctx context.Context, arg PutBoxSecretParams) error {
	_, err := q.db.ExecContext(ctx, putBoxSecret,
		arg.BoxID,
		arg.App,
		arg.Name,
		arg.ValueEnc,
		arg.Size,
		arg.Secret,
		arg.UpdatedAt,
	)
	return err
}

