const sumBoxSecretSize = `-- name: SumBoxSecretSize :one
SELECT CAST(COALESCE(SUM(size), 0) AS INTEGER) FROM box_secrets WHERE box_id = ?1 AND app = ?2 AND name <> ?3
`

type SumBoxSecretSizeParams struct {
	BoxID string `json:"boxId"`
	App   string `json:"app"`
	Name  string `json:"name"`
}

// Total size of the app's secrets except the one named @name (the one being replaced).
func (q *Queries) SumBoxSecretSize(ctx context.Context, arg SumBoxSecretSizeParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, sumBoxSecretSize, arg.BoxID, arg.App, arg.Name)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}
